import React, { useState, useEffect, useRef } from 'react';
import { useLocation, useNavigate, Link } from 'react-router-dom';
// eslint-disable-next-line @typescript-eslint/no-unused-vars
import { motion } from 'framer-motion';
// DeepSeek ve LLaMA servisleri yerine OpenAI servislerini kullanacağız
import { getCombinedAuraDataFromOpenAI } from '../../services/openaiService';
import { saveAuraStory } from '../../services/auraDataService';
// JSON dosyasından ruh hali quiz verilerini doğrudan alıyoruz
import moodQuizData from '../../data/quizzes/moodQuiz.json';
import Tooltip from '@mui/material/Tooltip';
import Modal from '@mui/material/Modal';
import Box from '@mui/material/Box';
import Button from '@mui/material/Button';
import CloseIcon from '@mui/icons-material/Close';
import IconButton from '@mui/material/IconButton';
import NavigationBar from '../../components/NavigationBar/NavigationBar';
import ErrorPage from '../../components/ErrorPage/ErrorPage';
import { toPng } from 'html-to-image';
import { saveAs } from 'file-saver';
import { Card, Typography, Backdrop, CircularProgress } from '@mui/material';
import ReactGA from 'react-ga4';
import BrainIcon from '../../assets/icons/brain-icon.svg';
import DiamondIcon from '../../assets/icons/diamond-icon.svg';
import StarIcon from '../../assets/icons/star-icon.svg';
import NoteIcon from '../../assets/icons/note-icon.svg';
import Footer from '../../components/Footer/Footer';
import './MoodResult.css';
import { BACKEND_URL } from '../../config';

// Quiz sorusu ve Quiz cevap seçeneği tipleri
interface QuizOption {
  id: string;
  value: string;
  [key: string]: any; // Diğer olası alanlar için
}

interface QuizQuestion {
  id: number;
  question: string;
  options: QuizOption[];
}

// Quiz cevabı için tip tanımlaması
interface DetailedAnswer {
  questionId: number;
  question: string;
  answerId: string;
  answerText: string;
}

// Yükleme animasyonu bileşeni
const LoadingAnimation = ({ text, color }: { text: string, color?: string }) => (
  <div className="loading-crystal">
    <div 
      className="loading-crystal-spinner" 
      style={{ 
        background: color || 'linear-gradient(135deg, #FF61D2, #FE9090)'
      }}
    ></div>
    <div className="loading-crystal-text">
      {text}<span className="loading-crystal-dots"></span>
    </div>
  </div>
);

// İçgörü yükleme bileşeni - daha özel animasyonlu versiyon
const InsightLoadingSkeleton = ({ icon, title, color }: { icon: string, title: string, color?: string }) => (
  <div className="insight-loading-skeleton">
    <div className="insight-loading-icon-container">
      <div 
        className="insight-loading-icon-placeholder" 
        style={{ background: color || 'linear-gradient(135deg, #FF61D2, #FE9090)' }}
      >
        <span className="insight-loading-icon">{icon}</span>
      </div>
    </div>
    <h3 className="insight-loading-title">{title}</h3>
    <div className="insight-loading-content-placeholder">
      <div className="insight-loading-crystal-container">
        <div className="insight-loading-crystal"></div>
      </div>
      <p className="insight-loading-text">İçgörüler yükleniyor<span className="insight-loading-dots"></span></p>
    </div>
  </div>
);

// Ana durum (mood) renkleri
const moodGradients = {
  main: 'linear-gradient(135deg, #43C6AC, #F8FFAE)',
  dark: 'linear-gradient(135deg, #2B7F6E, #A5AB4A)',
  light: '#43C6AC'
};

// Kristal yükleme ekranı CSS stilleri
const crystalLoadingStyles = `
.loading-screen {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  background: #fafafa;
  z-index: 1000;
}

.aura-crystal-container {
  position: relative;
  width: 200px;
  height: 200px;
  perspective: 1000px;
  margin-bottom: 40px;
}

.aura-crystal {
  position: absolute;
  width: 100%;
  height: 100%;
  transform-style: preserve-3d;
  animation: rotate 8s infinite linear;
}

@keyframes rotate {
  0% {
    transform: rotateY(0) rotateX(0);
  }
  100% {
    transform: rotateY(360deg) rotateX(360deg);
  }
}

.crystal-face {
  position: absolute;
  width: 100%;
  height: 100%;
  background: rgba(255, 255, 255, 0.7);
  border: 1px solid rgba(255, 255, 255, 0.8);
  backface-visibility: visible;
}

.face1 {
  transform: rotateY(0deg) translateZ(70px);
  background: linear-gradient(45deg, rgba(67, 198, 172, 0.4), rgba(248, 255, 174, 0.4));
}

.face2 {
  transform: rotateY(90deg) translateZ(70px);
  background: linear-gradient(45deg, rgba(67, 198, 172, 0.5), rgba(248, 255, 174, 0.5));
}

.face3 {
  transform: rotateY(180deg) translateZ(70px);
  background: linear-gradient(45deg, rgba(67, 198, 172, 0.6), rgba(248, 255, 174, 0.6));
}

.face4 {
  transform: rotateY(270deg) translateZ(70px);
  background: linear-gradient(45deg, rgba(67, 198, 172, 0.7), rgba(248, 255, 174, 0.7));
}

.crystal-shadow {
  position: absolute;
  bottom: -40px;
  left: 50%;
  transform: translateX(-50%);
  width: 80%;
  height: 20px;
  background: rgba(0, 0, 0, 0.1);
  border-radius: 50%;
  filter: blur(10px);
}

.loading-progress {
  width: 80%;
  max-width: 300px;
  margin-bottom: 20px;
}

.loading-bar {
  height: 6px;
  background: #eaeaea;
  border-radius: 3px;
  overflow: hidden;
  margin-bottom: 10px;
}

.loading-fill {
  height: 100%;
  transition: width 0.3s ease;
}

.loading-percentage {
  text-align: center;
  font-weight: 600;
  color: #333;
  margin: 0;
}

.loader-text {
  font-size: 1.5rem;
  font-weight: 600;
  color: #333;
  margin: 10px 0 5px;
}

.loader-subtext {
  font-size: 1rem;
  color: #666;
  margin: 0;
}

.insight-card {
  cursor: pointer;
  transition: transform 0.3s ease, box-shadow 0.3s ease;
  height: 100%;
  display: flex;
  flex-direction: column;
  position: relative;
  overflow: hidden;
}

.insight-card:hover {
  transform: translateY(-5px);
  box-shadow: 0 10px 20px rgba(0, 0, 0, 0.1);
}

.insight-content {
  flex: 1;
  overflow: hidden;
  position: relative;
}

.fade-overlay {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 50px;
  background: linear-gradient(to bottom, rgba(255, 255, 255, 0), rgba(255, 255, 255, 1));
}

.show-more-btn {
  margin-top: auto;
  text-align: center;
  background: linear-gradient(90deg, #43C6AC, #F8FFAE);
  color: white;
  border: none;
  border-radius: 4px;
  padding: 8px 16px;
  cursor: pointer;
  font-weight: 600;
  transition: opacity 0.3s ease;
  width: 100%;
}

.show-more-btn:hover {
  opacity: 0.9;
}

.modal-content {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 90%;
  max-width: 800px;
  max-height: 90vh;
  background-color: white;
  border-radius: 8px;
  padding: 24px;
  overflow-y: auto;
  outline: none;
  box-shadow: 0px 4px 20px rgba(0, 0, 0, 0.2);
}

.modal-header {
  display: flex;
  align-items: center;
  margin-bottom: 16px;
  position: sticky;
  top: 0;
  background: white;
  z-index: 1;
  padding-bottom: 8px;
  border-bottom: 1px solid #f0f0f0;
}

.modal-icon {
  width: 32px;
  height: 32px;
  margin-right: 12px;
}

.modal-title {
  flex: 1;
  font-size: 1.5rem;
  font-weight: 600;
}

.modal-body {
  font-size: 1rem;
  line-height: 1.6;
  white-space: pre-wrap;
}
`;

// Özel stil etiketini ekle
const LoadingStyles = () => {
  return <style>{crystalLoadingStyles}</style>;
};

// Duygu Durum Analizi Sonuç Sayfası
const MoodResult: React.FC = () => {
  const location = useLocation();
  const navigate = useNavigate();
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  const [isLoading, setIsLoading] = useState(true);
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  const [loadingProgress, setLoadingProgress] = useState(0);
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  const [isAnalysisStarted, setIsAnalysisStarted] = useState(false);
  const [moodStory, setMoodStory] = useState<string>('');
  const [moodStrengths, setMoodStrengths] = useState<string>('');
  const [moodPotential, setMoodPotential] = useState<string>('');
  const [moodThinking, setMoodThinking] = useState<string>('');
  const [moodTitle, setMoodTitle] = useState<string>('');
  const [auraId, setAuraId] = useState<string | null>(null);
  const [showShareButton, setShowShareButton] = useState(false);
  const [isSharing, setIsSharing] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const [isStoryLoading, setIsStoryLoading] = useState(true);
  const [isInsightsLoading, setIsInsightsLoading] = useState(true);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const [expandedCard, setExpandedCard] = useState<string | null>(null);
  const [openModal, setOpenModal] = useState<string | null>(null);
  const [modalTitle, setModalTitle] = useState<string>('');
  const [modalContent, setModalContent] = useState<React.ReactNode | null>(null);
  const [modalIcon, setModalIcon] = useState<string>('');

  useEffect(() => {
    const handleScroll = () => {
      if (window.scrollY > 50) {
        setScrolled(true);
      } else {
        setScrolled(false);
      }
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // Yükleme animasyonu
  useEffect(() => {
    // Yükleme animasyonu için interval oluştur
    const loadingInterval = setInterval(() => {
      setLoadingProgress(prev => {
        if (prev >= 100) return 100;
        return prev + 1;
      });
    }, 25);

    // 2.5 saniye sonra yükleme ekranını kaldır
    setTimeout(() => {
      setIsLoading(false);
    }, 2500);

    return () => {
      clearInterval(loadingInterval);
    };
  }, []);

  // Konum durum verilerini al
  useEffect(() => {
    const state = location.state as { answers: { [key: number]: string }; quizType: string } | null;

    if (!state || !state.answers) {
      // Eğer cevaplar yoksa ana sayfaya yönlendir
      navigate('/');
      return;
    }

    const quizType = 'mood'; // Bu sayfada sabit olarak 'mood' kullanılacak

    // Kullanıcı adını localStorage'dan al veya varsayılan
    const username = localStorage.getItem('auralize_username') || 'Seyyah';

    // Timeout kontrolü için
    let isTimedOut = false;
    let maxTimeout = 300000; // 5 dakika timeout

    const generateMoodAnalysis = async () => {
      setIsAnalysisStarted(true);
      timerRef.current = setTimeout(() => {
        if (isStoryLoading || isInsightsLoading) {
          isTimedOut = true;
          console.warn("Duygu durum analizi zaman aşımına uğradı");
          setMoodStory("Duygu durum analiziniz için sunucu yanıt vermedi. Bu genellikle geçici bir sorundur. Lütfen daha sonra tekrar deneyin.");
          setMoodStrengths("Zaman aşımı nedeniyle duygusal güçlü yönleriniz yüklenemedi.");
          setMoodPotential("Zaman aşımı nedeniyle duygusal potansiyeliniz yüklenemedi.");
