                  onClick={() => {
                    const formattedPotential = moodPotential.split('\n\n').map((paragraph, idx) => 
                      <p key={idx}>{paragraph}</p>
                    );

                    setModalContent(formattedPotential);
                    setModalTitle('Duygusal Potansiyelin');
                    setModalIcon('🚀');
                    setOpenModal('potential');
                  }}
                >
                  {isInsightsLoading ? (
                    <InsightLoadingSkeleton 
                      icon="🚀" 
                      title="Duygusal Potansiyelin" 
                      color={moodGradients.main}
                    />
                  ) : (
                    <>
                      <div className="mood-insight-icon">🚀</div>
                      <h3 className="mood-insight-title">Duygusal Potansiyelin</h3>
                      <div className="insight-content">
                        <div className="insight-content-gradient"></div>
                        <p className="mood-insight-text">
                          {moodPotential}
                        </p>
                      </div>
                      <div className="insight-card-expand-hint">
                        <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                          <path d="M15 3h6v6"></path>
                          <path d="M10 14 21 3"></path>
                        </svg>
                        Daha Fazla Göster
                      </div>
                    </>
                  )}
                </div>

                <div 
                  className="mood-insight-card"
                  onClick={() => {
                    const formattedThinking = moodThinking.split('\n\n').map((paragraph, idx) => 
                      <p key={idx}>{paragraph}</p>
                    );

                    setModalContent(formattedThinking);
                    setModalTitle('Duygusal Tepki Stilin');
                    setModalIcon('🧠');
                    setOpenModal('thinking');
                  }}
                >
                  {isInsightsLoading ? (
                    <InsightLoadingSkeleton 
                      icon="🧠" 
                      title="Duygusal Tepki Stilin" 
                      color={moodGradients.main}
                    />
                  ) : (
                    <>
                      <div className="mood-insight-icon">🧠</div>
                      <h3 className="mood-insight-title">Duygusal Tepki Stilin</h3>
                      <div className="insight-content">
                        <div className="insight-content-gradient"></div>
                        <p className="mood-insight-text">
                          {moodThinking}
                        </p>
                      </div>
                      <div className="insight-card-expand-hint">
                        <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                          <path d="M15 3h6v6"></path>
                          <path d="M10 14 21 3"></path>
                        </svg>
                        Daha Fazla Göster
                      </div>
                    </>
                  )}
                </div>
              </div>
            </section>

            {/* Modal Component */}
            {openModal && (
              <div className="insight-modal" onClick={() => setOpenModal(null)}>
                <div className="modal-content" onClick={(e) => e.stopPropagation()}>
                  <button className="modal-close" onClick={() => setOpenModal(null)}>×</button>
                  <div className="modal-header">
                    <div className="modal-icon">{modalIcon}</div>
                    <h2 className="modal-title">{modalTitle}</h2>
                  </div>
                  <div className="modal-body">
                    {modalContent}
                  </div>
                </div>
              </div>
            )}

            {/* Aksiyon Butonları */}
            <div className="mood-actions">
              <Link to="/" className="btn btn-primary">
                Ana Sayfaya Dön
              </Link>
              <Link to="/quiz?type=mood" className="btn btn-glass">
                <span className="btn-icon">🔄</span>
                Testi Tekrarla
              </Link>
              {showShareButton && (
                <button 
                  className={`btn ${isSharing ? 'btn-success' : 'btn-share'}`}
                  onClick={handleShareAnalysis}
                  disabled={isSharing}
                >
                  <span className="btn-icon">
                    {isSharing ? '✓' : (
                      <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                        <circle cx="18" cy="5" r="3"></circle>
                        <circle cx="6" cy="12" r="3"></circle>
                        <circle cx="18" cy="19" r="3"></circle>
                        <line x1="8.59" y1="13.51" x2="15.42" y2="17.49"></line>
                        <line x1="15.41" y1="6.51" x2="8.59" y2="10.49"></line>
                      </svg>
                    )}
                  </span>
                  {isSharing ? 'Paylaşıldı' : 'Galeriye Paylaş'}
                </button>
              )}
            </div>
          </div>
        </main>

        <Footer />
      </div>
    </>
  );
};

export default MoodResult;
